// Full native normal indicial analysis. No additional evolved state.
#include "goal1_tensor_endpoint_amplitude.hpp"
#include <iostream>
#include <iomanip>
#include <string>
#include <cstdlib>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;using J=cs::Jet;using D=cs::tensor_endpoint::D;
Real Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("short native indicial input");char*e;Real v=std::strtod(s.c_str(),&e);if(*e||!std::isfinite(v))throw std::runtime_error("bad native indicial token");return v;}
struct Background{h::LayerPoint<D>p{};rwm::Connection<D>connection{};h::Z4cJet<D>u{};};
Background Reference(const Real n[3],Real rho){Background out;J omega(rho);omega.d[0]=1;J r=cs::Power(J(1)-omega,.5),x[3];for(int i=0;i<3;++i)x[i]=J(n[i])*r;auto&p=out.p;auto&u=out.u;p.omega=D(omega);p.L=p.alpha=u.alpha.value=D(J(2)-omega);p.radius=D(r);p.k_physical=u.trace.value=D(-6);p.k_bar=D(-6)/p.L;p.state.chi.value=u.chi.value=D(1);
 for(int i=0;i<3;++i){p.domega[i]=D(-J(2)*x[i]);p.dalpha[i]=u.alpha.d[i]=D(J(2)*x[i]);p.beta[i]=u.beta.value[i]=D(-J(2)*x[i]);for(int j=0;j<3;++j){u.metric.g[i][j]=D(i==j?1:0);p.omega_hessian[i][j]=D(i==j?-2:0);u.alpha.dd[i][j]=D(i==j?2:0);u.beta.d[i][j]=D(i==j?-2:0);out.connection.scaled[0][i][j]=i==j?D(2)/p.L:D(0);for(int k=0;k<3;++k)out.connection.scaled[k+1][i][j]=D(J(2)*((k==i?x[j]:J(0))+(k==j?x[i]:J(0))))+(i==j?D(J(2)*x[k])*p.omega/p.L:D(0));}}
 p.state=u;out.connection.valid=true;return out;}
void Seed(h::Z4cJet<D>&u,const h::LayerPoint<D>&p,int col,Real exponent,Real amplitude){J omega=p.omega.f;auto add=[&](D&v,const J&a){v.a+=a*J(amplitude);};auto scalar=[&](h::ScalarJet<D>&v){add(v.value,omega*omega);for(int i=0;i<3;++i){add(v.d[i],J(exponent)*omega*p.domega[i].f);for(int j=0;j<3;++j)add(v.dd[i][j],J(exponent*(exponent-1))*p.domega[i].f*p.domega[j].f+J(exponent)*omega*p.omega_hessian[i][j].f);}};
 if(col==0)scalar(u.chi);if(col==7)scalar(u.trace);if(col==17)scalar(u.theta);if(col==18)scalar(u.alpha);
 if(col>=1&&col<=6){int a=cs::native_endpoint::ma[col-1],b=cs::native_endpoint::mb[col-1];add(u.metric.g[a][b],omega*omega);if(a!=b)u.metric.g[b][a]=u.metric.g[a][b];for(int i=0;i<3;++i){add(u.metric.dg[i][a][b],J(exponent)*omega*p.domega[i].f);if(a!=b)u.metric.dg[i][b][a]=u.metric.dg[i][a][b];for(int j=0;j<3;++j){add(u.metric.ddg[i][j][a][b],J(exponent*(exponent-1))*p.domega[i].f*p.domega[j].f+J(exponent)*omega*p.omega_hessian[i][j].f);if(a!=b)u.metric.ddg[i][j][b][a]=u.metric.ddg[i][j][a][b];}}}
 if(col>=8&&col<=13){int a=cs::native_endpoint::ma[col-8],b=cs::native_endpoint::mb[col-8];add(u.a.k[a][b],omega);if(a!=b)u.a.k[b][a]=u.a.k[a][b];for(int i=0;i<3;++i){add(u.a.dk[i][a][b],J(exponent-1)*p.domega[i].f);if(a!=b)u.a.dk[i][b][a]=u.a.dk[i][a][b];}}
 if(col>=14&&col<=16){int a=col-14;add(u.lambda.value[a],omega);for(int i=0;i<3;++i)add(u.lambda.d[i][a],J(exponent-1)*p.domega[i].f);}
 if(col>=19){int a=col-19;add(u.beta.value[a],omega*omega);for(int i=0;i<3;++i){add(u.beta.d[i][a],J(exponent)*omega*p.domega[i].f);for(int j=0;j<3;++j)add(u.beta.dd[i][j][a],J(exponent*(exponent-1))*p.domega[i].f*p.domega[j].f+J(exponent)*omega*p.omega_hessian[i][j].f);}}
}
struct Matrix{Real L[22][22]{},C[8][22]{},negative=0,background=0;};
Matrix Extract(const Real n[3],Real exponent,Real rho,Real amplitude,int negative_mode=0){Matrix out;auto reference=Reference(n,rho);for(int col=0;col<22;++col){auto u=reference.u;Seed(u,reference.p,col,exponent,amplitude);h::OmegaJet<D>o{};o.omega=reference.p.omega;for(int i=0;i<3;++i){o.gradient[i]=reference.p.domega[i];for(int j=0;j<3;++j)o.hessian[i][j]=reference.p.omega_hessian[i][j];}h::SetStationaryOmegaNormal(u.alpha.value,u.beta.value,u.alpha.d,u.beta.d,o);auto f=h::ConformalRHS(u,o,D(10)/u.alpha.value,D(0));auto gauge=rwm::Gauge(reference.p,u,reference.connection);auto constraints=h::EvolvedConstraints(u,o);if(!f.valid||!gauge.valid||!constraints.valid)throw std::runtime_error("invalid actual native indicial system");
 if(negative_mode==1)f.pole.theta+=D(3)*u.alpha.value*o.normal*u.theta.value;
 if(negative_mode==2){auto g=h::Geometry(u.metric);for(int i=0;i<3;++i)for(int j=0;j<3;++j)for(int k=0;k<3;++k)for(int l=0;l<3;++l)f.pole.lambda[i]+=D(4)*u.alpha.value*g.inverse[i][k]*u.a.k[k][l]*g.inverse[l][j]*o.gradient[j];}
 auto R=cs::native_endpoint::Rows(f.regular,gauge.regular),S=cs::native_endpoint::Rows(f.pole,gauge.pole);
 for(int row=0;row<22;++row){const bool weight=row>=8&&row<=16;J r=R[row].a,s=S[row].a;Real value=0;if(rho>0)value=(r.f+s.f/rho)/(weight?1:rho);else if(weight){out.negative=std::max(out.negative,std::abs(s.f));value=r.f+s.d[0];}else{out.negative=std::max({out.negative,std::abs(s.f),std::abs(r.f+s.d[0])});value=r.d[0]+s.h[0][0]/2;}out.L[row][col]=value/amplitude;
  if(col==0){auto r0=R[row].f,s0=S[row].f;Real a0=rho>0?r0.f+s0.f/rho:r0.f+s0.d[0];out.background=std::max(out.background,std::abs(a0));}}
 D cc[8]={constraints.hamiltonian,constraints.momentum[0],constraints.momentum[1],constraints.momentum[2],u.theta.value,constraints.z4.z_covector[0],constraints.z4.z_covector[1],constraints.z4.z_covector[2]};for(int row=0;row<8;++row){bool two=row==0||row==4;J a=cc[row].a;Real value;if(rho>0)value=a.f/(two?rho*rho:rho);else if(two){out.negative=std::max({out.negative,std::abs(a.f),std::abs(a.d[0])});value=a.h[0][0]/2;}else{out.negative=std::max(out.negative,std::abs(a.f));value=a.d[0];}out.C[row][col]=value/amplitude;}}
 return out;}
template<int M,int N>void Print(const Real(&a)[M][N]){std::cout<<"[";for(int i=0;i<M;++i){if(i)std::cout<<",";std::cout<<"[";for(int j=0;j<N;++j)std::cout<<(j?",":"")<<a[i][j];std::cout<<"]";}std::cout<<"]";}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;std::cout<<std::setprecision(17);try{while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read();Real n[3];for(auto&v:n)v=Read();Real s=Read();auto a=Extract(n,s,0,1),half=Extract(n,s,0,.5);Real amplitude_error=0;for(int i=0;i<22;++i)for(int j=0;j<22;++j)amplitude_error=std::max(amplitude_error,std::abs(a.L[i][j]-half.L[i][j]));std::cout<<"{\"id\":"<<id<<",\"s\":"<<s<<",\"n\":["<<n[0]<<","<<n[1]<<","<<n[2]<<"],\"negative_laurent\":"<<a.negative<<",\"background_rhs\":"<<a.background<<",\"amplitude_error\":"<<amplitude_error<<",\"L\":";Print(a.L);std::cout<<",\"C\":";Print(a.C);std::cout<<",\"finite\":[";
 for(int j=0;j<3;++j){Real rho=j==0?.001:(j==1?.0001:.00001);auto f=Extract(n,s,rho,1);if(j)std::cout<<",";std::cout<<"{\"Omega\":"<<rho<<",\"L\":";Print(f.L);std::cout<<",\"C\":";Print(f.C);std::cout<<"}";}auto omitted=Extract(n,s,0,1,1),missing=Extract(n,s,0,1,2);std::cout<<"],\"negative_omit_tensor_Theta_L\":";Print(omitted.L);std::cout<<",\"negative_omit_Lambda_A_L\":";Print(missing.L);std::cout<<"}"<<std::endl;
 }}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
